const D = (id: string, l: string, html: string, cls: string = ""): void => add(id, "Desktop", l, html, cls);
const M = (id: string, l: string, html: string, cls: string = ""): void => add(id, "Mobile", l, html, cls, 880);
const X = (id: string, l: string, html: string, cls: string = "", w: number = 1440): void => add(id, "Explore", l, html, cls, w);
const libHead = (fld: string = ""): string => hrow("Everything", "248", fld);
const LIBV = (): string => libHead() + pills() + grid(LIB);
const behind = (): string => LIBV() + `<div class="dim"></div>`;
const searchFld = (q: string, right: string): string => `<div style="width:560px">${field(q + CUR, true, "foc", right)}</div>`;
const KIT: Card[][] = [[W("oak"), W("brass")], [W("lime"), W("work")], [W("tile"), W("oak", { k: "link", t: "Lime plaster for hallways: a practical guide", a: "g6", h: 170, src: "example-design.com" })]];

// ── Cards (the Library) ──────────────────────────────────────────────
D("d01", "Cards: Everything", desk(LIBV()));
D("d02", "Cards: one space", desk(hrow("Kitchen reno", "38") + pills("Kitchen reno") + grid(KIT)));
const spaceBand = (right: string): string => `<div class="band" style="--c:var(--coral);margin:24px 64px 0;padding:32px 40px;display:flex;justify-content:space-between;align-items:center"><div><div class="hero">Kitchen reno<sup style="color:var(--on-c);opacity:.6">38</sup></div><div class="body" style="opacity:.8;margin-top:8px">3 open tasks · last save 2h ago</div></div><div class="row" style="gap:12px;flex-wrap:nowrap">${right}</div></div>`;
const bandToggle = (on: string): string => `<div class="tg" style="background:rgba(255,255,255,.4)">${["Board", "Journal"].map((x: string) => `<span class="${x === on ? "on" : ""}" style="${x === on ? "" : "color:var(--on-c)"}">${x}</span>`).join("")}</div>${rb("•••")}`;
D("d03", "Space page: board", desk(spaceBand(bandToggle("Board")) + `<div style="display:grid;grid-template-columns:1fr 2fr;gap:32px;padding:32px 64px 0"><div class="col" style="gap:16px"><div class="sec">Pinned</div><div class="row" style="gap:12px">${["T", "P", "H"].map((x: string) => rb(x, "lg")).join("")}</div><div class="sec" style="margin-top:8px">Open tasks</div>${trow("Order three tile samples", "coral", "Nov 18")}${trow("Call the electrician", "coral", "Today")}${trow("Confirm the plasterer", "coral", "")}</div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start">${card(W("oak", { h: 200 }))}${card(W("lime"))}</div></div>`));
D("d04", "Search: results", desk(libHead(searchFld("plaster", `<span class="lab" style="margin-right:16px">2 cards · ↵ saves a jot</span>`)) + pills() + grid([[W("lime")], [W("oak", { k: "link", t: "Lime plaster for hallways: a practical guide", a: "g6", h: 190, src: "example-design.com" })], []])));
D("d05", "Search: no results", desk(libHead(searchFld("zellij tiles in blue", "")) + pills() + `<div style="margin-top:24px">${empty("No “zellij tiles in blue” cards", "Keep it as a jot instead?", `<div class="row" style="margin-top:8px">${btn("Save it as a jot", "p")}${btn("Clear", "q")}</div>`, "line", "⌕")}</div>`));
// The ••• opens one View panel: big layout tiles, then chips. Saved views sit at the bottom.
const chip = (t: string, on: boolean = false, extra: string = ""): string => `<div class="pill sm plain ${on ? "on" : ""}" style="${on ? "" : "box-shadow:0 0 0 2px var(--line) inset"}">${on ? "✓ " : ""}${t}${extra ? ` <em>${extra}</em>` : ""}</div>`;
const layTile = (g: string, t: string, on: boolean): string => `<div class="stile ${on ? "on" : ""}" style="--c:var(--ink);color:${on ? "var(--paper)" : "var(--ink)"};min-height:112px;align-items:center;justify-content:center;gap:8px;padding:16px"><div style="font:900 32px var(--fd)">${g}</div><div class="h3" style="font-size:20px">${t}</div></div>`;
const viewPanel = (): string => `<div class="sheet" style="right:64px;top:176px;width:600px;padding:32px;z-index:6"><div class="row" style="justify-content:space-between"><div class="h2">View</div>${btn("Reset", "q sm")}</div>
<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:24px">${layTile("▦", "Cards", true)}${layTile("☰", "List", false)}${layTile("▤", "Table", false)}</div>
<div class="sec" style="margin:24px 0 12px">Show</div><div class="row" style="gap:8px">${chip("Links", true)}${chip("Notes", true)}${chip("Tasks", true)}${chip("Unfiled only")}</div>
<div class="sec" style="margin:24px 0 12px">From</div><div class="row" style="gap:8px">${chip("X")}${chip("Pinterest")}${chip("YouTube")}${chip("Web")}</div>
<div class="sec" style="margin:24px 0 12px">Sort</div><div class="row" style="gap:8px">${chip("Updated", true)}${chip("Saved")}${chip("Title")}${chip("More…")}</div>
<div class="sec" style="margin:24px 0 12px">Saved views</div><div class="row" style="gap:8px">${chip("From X", false, "12")}${chip("Kitchen moodboard", false, "4")}<div class="pill sm plain add">+ Save view</div></div></div>`;
D("d06", "View panel (•••): layout, filters, sort, views", desk(LIBV() + `<div class="dim" style="background:rgba(30,36,52,.18);backdrop-filter:none"></div>` + viewPanel()));
D("d07", "List layout", desk(libHead() + pills() + `<div class="col" style="gap:16px;padding:32px 64px 0">${[W("oak"), W("brass"), W("bamboo"), W("calm"), W("join")].map((c: Card, i: number) => lrow(c, "", ["2h", "3h", "Mon", "Sun", "Sat"][i])).join("")}</div>`));
D("d08", "Table layout", desk(libHead() + pills() + `<div style="padding:32px 64px 0"><div class="tbl"><div class="tr th"><span>Title ↓</span><span>Type</span><span>Source</span><span>Space</span><span>Saved</span></div>${[["g1", "Warm oak shelving", "Picture", "Pinterest", "Kitchen reno", "coral", "2h"], ["g3", "Arashiyama bamboo grove", "Link", "Web", "Kyoto trip", "cyan", "Mon"], ["g4", "Japanese joinery, no nails", "Link", "YouTube", "Reading", "gold", "Sun"], ["g6", "Lime plaster, not paint", "Note", "memex", "Kitchen reno", "coral", "Sat"], ["g2", "A tiny type scale", "Link", "X", "Studio", "blue", "Nov 9"], ["g5", "How to plan a reading year", "Link", "Web", "Reading", "gold", "Nov 8"]].map((r: string[], i: number) => `<div class="tr ${i === 1 ? "" : ""}" style="${i === 1 ? "background:var(--well)" : ""}"><span class="t1"><span class="art ${r[0]}"></span>${r[1]}</span><span>${r[2]}</span><span>${r[3]}</span><span>${strip(r[4], r[5])}</span><span>${r[6]}</span></div>`).join("")}</div></div>`));
const selBar = (n: string): string => `<div style="position:absolute;left:50%;transform:translateX(-50%);bottom:40px;display:flex;align-items:center;gap:12px;background:var(--toast);color:#fff;border-radius:999px;padding:8px 8px 8px 32px;box-shadow:var(--sh3);z-index:6"><span class="h3" style="color:#fff;margin-right:12px">${n} selected</span>${btn("Move to…", "p sm")}${btn("Delete", "d sm")}${rb("✕", "sm")}</div>`;
D("d09", "Select many: bar", desk(libHead() + pills() + grid([[W("oak", { st: "selc", tick: "on" }), W("type", { tick: "off" })], [W("brass", { st: "selc", tick: "on" }), W("bamboo", { tick: "off" })], [W("join", { st: "selc", tick: "on" }), W("tile", { tick: "off" })]]) + selBar("3")));
D("d10", "Drag cards onto a space", desk(libHead() + `<div class="pills">${allPill(false)}${pill("Kitchen reno", "coral")}${pill("Kyoto trip", "cyan")}${pill("Add 2 to Reading", "gold", "", "drop", "+")}${pill("Studio", "blue")}${addPill()}</div>` + grid([[W("oak"), W("type")], [W("brass", { st: "ghost" }), W("bamboo")], [W("join", { st: "ghost" }), W("tile")]]) + `<div style="position:absolute;left:560px;top:300px;width:330px;z-index:6">${card(W("join", { st: "drag", h: 140 }))}<span class="bdg" style="background:var(--pri);color:#fff;right:-12px;top:-12px;box-shadow:0 0 0 3px var(--paper)">2</span></div>`));

// ── Opening a card ───────────────────────────────────────────────────
const openCard = (menuOpen: boolean): string => desk(behind() + `<div class="sheet" style="left:160px;top:72px;width:1120px;height:756px;padding:0"><div style="position:absolute;inset:0;border-radius:40px;overflow:hidden;padding:24px;display:flex;gap:48px"><div class="art g4" style="width:560px;border-radius:28px;flex:none"></div><div style="flex:1;display:flex;flex-direction:column;padding:24px 24px 0 0"><div class="row" style="gap:8px">${pill("Reading", "gold", "", "sel sm")}<div class="pill sm plain add">+ Space</div></div><div class="h1" style="margin-top:32px;font-size:48px">Japanese joinery holds a house together without nails</div><div class="lab" style="margin-top:16px">youtube.com · saved Monday</div><div class="body" style="margin-top:24px;color:var(--mut)">A carpenter walks through six joints, from the simplest lap to a hidden dovetail.</div><div class="row" style="margin-top:auto;gap:12px;flex-wrap:nowrap;padding-bottom:24px">${btn("Open ↗", "p")}${rb("•••", menuOpen ? "foc" : "")}</div></div><div class="lb" style="--c:var(--gold);position:absolute;left:0;right:0;bottom:0;margin:0;height:24px"></div></div><div class="x">${rb("✕")}</div></div>` + (menuOpen ? menu(["⧉|Copy link||hov", "✎|Edit title, link, note…", "★|Pin to top", "↻|Refresh preview", "-", "✕|Delete|⌫|dz"], "left:820px;top:430px") : ""));
D("d11", "Card open: link", openCard(false));
D("d12", "Card open: ••• menu", openCard(true));
D("d13", "Edit a link", desk(behind() + sheet("left:370px;top:96px;width:700px", `<div class="h2">Edit card</div><div class="flab">Link</div>${inp("https://example-video.com/watch/joinery")}<div class="flab">Title</div>${inp("Japanese joinery holds a house together without nails", "foc")}<div class="flab">Why I saved this</div>${inp("Optional note", "ph")}<div class="sf">${btn("Cancel", "q")}${btn("Save", "p")}</div>`)));
const moveTile = (n: string, c: string, st: string, sub: string): string => `<div class="tile ${st}" style="--c:var(--${c});min-height:120px;padding:20px"><div class="row" style="justify-content:space-between;align-items:flex-start"><span class="lab" style="color:var(--on-c);opacity:.75">${sub}</span>${st === "sel" ? `<span class="chk on" style="background:var(--paper);color:var(--ink);box-shadow:none">✓</span>` : ""}</div><div class="nm">${n}</div></div>`;
D("d14", "Move to a space", desk(behind() + sheet("left:320px;top:110px;width:800px", `<div class="h2">Move 3 cards to…</div><div class="body" style="color:var(--mut);margin-top:8px">A card can live in more than one space.</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:24px">${moveTile("Kitchen reno", "coral", "sel", "All in")}${moveTile("Kyoto trip", "cyan", "hov", "")}${moveTile("Reading", "gold", "", "")}${moveTile("Studio", "blue", "", "")}<div class="tile" style="--c:transparent;border:3px dashed var(--line);box-shadow:none;color:var(--mut);min-height:120px;padding:20px;justify-content:center;align-items:center"><div class="nm" style="margin:0">+ New space</div></div></div><div class="sf">${btn("Take out of all", "q")}${btn("Done", "p")}</div>`)));
D("d15", "Note open: editor", desk(`<div class="note-doc" style="--c:var(--coral)"><div class="lb" style="margin:0 -72px 48px;height:64px;padding:0 24px 0 72px;font-size:20px"><span>Kitchen reno <span style="opacity:.6;font-weight:700">+ Space</span></span><span class="row" style="gap:12px;flex-wrap:nowrap"><i>Saved</i>${rb("•••", "sm")}${rb("✕", "sm")}</span></div><div class="md"><h1>Hallway finish</h1><p>Lime plaster, not paint. It breathes, and scuffs can be patched.</p><h2><span class="mk">## </span>Ask the plasterer</h2><div class="li"><span class="chk on">✓</span>Curing time before furniture</div><div class="li"><span class="chk"></span>Tint samples in warm white</div><div class="li"><span class="chk"></span>Price per square metre<span class="cur"></span></div></div></div>`));
D("d16", "Image card open", desk(behind() + `<div class="sheet" style="left:290px;top:56px;width:860px;height:800px;padding:24px"><div class="art g1" style="height:560px;border-radius:28px"></div><div class="row" style="justify-content:space-between;margin-top:24px;padding:0 16px;flex-wrap:nowrap"><div><div class="h2">Warm oak shelving over a zellige backsplash</div><div class="row" style="gap:12px;margin-top:12px">${pill("Kitchen reno", "coral", "", "sel xs")}<span class="lab">pinterest · saved 2h ago</span></div></div><div class="row" style="gap:12px;flex-wrap:nowrap">${btn("Open ↗", "p")}${rb("•••")}</div></div><div class="x">${rb("✕")}</div></div>`));
D("d17", "Delete with Undo", desk(libHead() + pills() + grid([[W("oak"), W("type")], [W("bamboo"), W("read")], [W("join"), W("tile")]]) + toast("Deleted “Lime plaster, not paint”", "Undo", "pos", "line", "✕")));

// ── Capture: the sheet previews the card you are about to write ─────
const putIn = (sel: string): string => `<div class="sec" style="margin:24px 0 12px">Put it in</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">${SP.map((s: [string, string, string]) => pill(s[0], s[1], "", s[0] === sel ? "sel sm" : "sm")).join("")}</div>`;
const capSheet = (top: number, kind: string, well: string, extra: string, preview: string, foot: string): string => desk(behind() + sheet(`left:200px;top:${top}px;width:1040px;padding:48px`, `<div class="row" style="justify-content:space-between"><div class="h1">Save something</div>${kind ? `<div class="tg">${["Jot", "Note", "Task"].map((x: string) => `<span class="${x === kind ? "on" : ""}">${x}</span>`).join("")}</div>` : ""}</div><div style="display:grid;grid-template-columns:1fr 300px;gap:40px;margin-top:32px;align-items:start"><div>${well}${extra}</div><div><div class="sec" style="margin-bottom:12px">Your card</div>${preview}</div></div>${foot}`));
D("d18", "Capture: link", capSheet(80, "", `<div style="border-radius:28px;background:var(--well);padding:24px 32px;font:500 22px/1.4 var(--fu)">https://example-design.com/lime-plaster</div>`, putIn("Kitchen reno"), card(W("lime", { k: "link", t: "Lime plaster for hallways: a practical guide", a: "g6", h: 140, src: "example-design.com" })), `<div class="sf"><span class="lab"><span class="kb">↵</span> save · <span class="kb">Esc</span> close</span>${btn("Save", "p")}</div>`));
D("d19", "Capture: note", capSheet(80, "Note", `<div style="border-radius:28px;background:var(--well);padding:24px 32px;height:232px"><div class="h2">Hallway finish</div><div class="body" style="margin-top:12px">Lime plaster, not paint. It breathes, and scuffs can be patched.${CUR}</div></div>`, putIn("Kitchen reno"), card(W("lime", { t: "Hallway finish" })), `<div class="sf"><span class="lab"><span class="kb">⌘↵</span> saves the note</span>${btn("Save note", "p")}</div>`));
D("d20", "Capture: task", capSheet(100, "Task", `<div class="row" style="border-radius:28px;background:var(--well);padding:24px 28px;flex-wrap:nowrap"><div class="chk lg"></div><div class="h2" style="flex:1">Order three tile samples${CUR}</div></div><div class="sec" style="margin:24px 0 12px">Due</div><div class="tg"><span>None</span><span class="on">Tomorrow</span><span>Next week</span><span>Pick a date…</span></div>`, putIn("Kitchen reno"), card(W("tile", { due: "Tomorrow" })), `<div class="sf"><span class="lab">Tip: type [] in any field</span>${btn("Add task", "p")}</div>`));
D("d21", "Capture: offline error", desk(behind() + sheet("left:200px;top:200px;width:1040px;padding:48px", `<div class="h1">Save something</div><div style="margin-top:32px;border-radius:28px;background:var(--well);padding:24px 32px;font:500 24px/1.4 var(--fu);box-shadow:0 0 0 3px var(--err)">Ask about curing time before furniture goes in</div><div class="ferr" style="font-size:18px;margin-top:16px">Couldn’t reach memex. Your words are kept here, and it retries on its own.</div><div class="sf">${btn("Close", "q")}${btn("Retry", "p")}</div>`)));
D("d22", "Capture: saved (card-write)", desk(libHead() + pills() + grid([[W("ryo", { st: "write", k: "note", t: "Ask about curing time before furniture goes in.", c: "coral", sn: "Kitchen reno" }), W("oak", { h: 220 })], [W("brass"), W("bamboo")], [W("join"), W("tile")]]) + toast("Saved to Kitchen reno", "Open", "pos", "coral")));

// ── Journal ──────────────────────────────────────────────────────────
const jPage = (inner: string, head: string = `<div class="hero" style="font-size:64px">Today<sup>11</sup></div>`, sty: string = "left:200px;right:200px"): string => `<div style="position:absolute;${sty};top:112px;bottom:0;background:var(--paper);border-radius:40px 40px 0 0;box-shadow:var(--sh2);padding:40px 56px">${head}<div style="margin-top:24px">${inner}</div><div style="position:absolute;left:56px;right:56px;bottom:32px">${field("Write a jot, paste a link…", false, "", plusBtn())}</div></div>`;
const jFeed = (): string => `${bub("Sage green island, warm oak shelves. Keep the worktop pale.", "8:02 AM", strip("Kitchen reno", "coral"))}<div class="jrow"><div style="width:440px">${card(W("join", { h: 72 }))}</div></div>${bub("Ask about the onsen ryokan near the river.", "9:10 AM", strip("Kyoto trip", "cyan", true))}`;
D("d23", "Journal (17B) desktop", desk(jPage(jFeed()), "", "Journal"));
D("d24", "Journal: entry actions", desk(jPage(`${bub("Sage green island, warm oak shelves. Keep the worktop pale.", "8:02 AM", strip("Kitchen reno", "coral"))}<div class="jrow"><div class="bub" style="box-shadow:0 0 0 4px var(--ring),var(--sh1)">Brass pulls, not black.<small>8:14 AM</small></div></div>`) + menu(["●|File in…|→|hov", "✎|Edit", "▤|Make it a note", "☐|Make it a task", "-", "✕|Delete|⌫|dz"], "left:620px;top:390px"), "", "Journal"));

// ── Inbox and Tasks ──────────────────────────────────────────────────
D("d25", "Inbox", desk(`<div class="hrow">${heroT("Inbox", "3")}</div><div style="display:grid;grid-template-columns:1.15fr 1fr;gap:40px;padding:32px 64px 0;align-items:start"><div class="col" style="gap:16px"><div class="sec">From agents</div>${proposal()}</div><div class="col" style="gap:16px"><div class="sec">To file</div>${suggestion()}${suggestion("Reading lamp with a linen shade", "Mentions “lamp” and “reading”", "Reading", "gold", "g6")}</div></div>`, "", "Cards", "3"));
D("d26", "Inbox: all clear", desk(`<div class="hrow">${heroT("Inbox", "0")}</div><div style="margin-top:56px">${empty("Everything is filed", "Agents’ proposals and filing ideas land here.", "", "ok", "✓")}</div>`, "", "Cards", ""));
const taskCol = (n: string, c: string, cnt: string, rows: string): string => `<div class="col" style="gap:12px"><div class="band" style="--c:var(--${c});border-radius:24px;height:64px;padding:0 24px;display:flex;align-items:center;justify-content:space-between"><span class="h3" style="font-size:24px">${n}</span><span style="font:800 20px var(--fu);opacity:.7">${cnt}</span></div>${rows}</div>`;
D("d27", "Tasks", desk(`<div class="hrow">${heroT("Tasks", "6")}<div class="row" style="gap:12px;flex-wrap:nowrap"><div style="width:480px">${field("Add a task…", false, "", `<span class="kb" style="margin-right:16px">N</span>`)}</div><div class="tg"><span class="on">By space</span><span>By date</span></div>${rb("•••")}</div></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:32px;padding:32px 64px 0">${taskCol("Kitchen reno", "coral", "3", trow("Order three tile samples", "coral", "Nov 18") + trow("Call the electrician", "coral", "Today", "hov") + trow("Confirm the plasterer", "coral"))}${taskCol("Kyoto trip", "cyan", "3", trow("Renew passport photos", "cyan", "late 2 days late") + trow("Book the ryokan", "cyan", "Fri") + trow("Buy a rail pass", "cyan"))}</div><div style="padding:24px 64px 0">${btn("▸ Done (4)", "q sm")}</div>`, "", "Tasks"));
D("d28", "Task menu: due date", desk(`<div class="hrow">${heroT("Tasks", "6")}</div><div class="col" style="gap:12px;padding:32px 64px 0;width:820px">${trow("Order three tile samples", "coral", "Nov 18", "foc", "Kitchen reno")}${trow("Call the electrician", "coral", "Today", "", "Kitchen reno")}</div>` + menu(["#Due", "|Today", "|Tomorrow||hov", "|Next week", "|Pick a date…", "|No due date", "-", "✎|Rename…|↵", "●|File in…", "✕|Delete|⌫|dz"], "left:560px;top:300px"), "", "Tasks"));

// ── Spaces, settings, tokens ─────────────────────────────────────────
D("d29", "New space", desk(behind() + sheet("left:380px;top:180px;width:680px", `<div class="h2">New space</div><div class="flab">Name</div>${inp("Garden" + CUR, "foc")}<div class="flab">Colour</div><div class="row" style="gap:12px">${COLS.map((c: string, i: number) => `<div class="sw ${i === 5 ? "sel" : ""}" style="--c:var(--${c})"></div>`).join("")}</div><div class="sf">${btn("Cancel", "q")}${btn("Create", "p")}</div>`)));
D("d30", "Space settings and delete", desk(hrow("Kitchen reno", "38") + pills("Kitchen reno") + grid(KIT) + `<div class="dim"></div>` + sheet("left:400px;top:120px;width:640px", `<div class="h2">Kitchen reno</div><div class="flab">Name</div>${inp("Kitchen reno")}<div class="flab">Colour</div><div class="row" style="gap:12px">${COLS.slice(0, 6).map((c: string, i: number) => `<div class="sw ${i === 0 ? "sel" : ""}" style="--c:var(--${c})"></div>`).join("")}</div><div class="flab">Holds</div><div class="body">21 links · 9 notes · 5 tasks · 3 jots</div><div class="sf">${btn("Delete space", "d sm")}${btn("Save", "p")}</div><div class="lab" style="margin-top:16px">Deleting a space keeps its cards.</div>`)));
const stile = (t: string, v: string, on: boolean, c: string, ctl: string = ""): string => `<div class="stile ${on ? "on" : ""}" style="--c:var(--${c})"><div class="h3">${t}</div><div class="lab">${v}</div>${ctl}</div>`;
