X("x03", "Nav C: bento of space tiles", `<div class="frame"><div class="top"><div class="wm">memex</div><div class="seg">${["Journal", "Cards", "Tasks"].map((x: string) => `<span class="${x === "Cards" ? "on" : ""}">${x}</span>`).join("")}</div><div class="row" style="gap:12px;flex-wrap:nowrap"><div style="width:420px">${field("Search or save…", false, "", plusBtn())}</div>${inboxBtn("5")}${rb("D")}</div></div><div style="display:grid;grid-template-columns:repeat(5,1fr) 120px;gap:16px;padding:32px 64px 0">${bentoTile("Everything", "ink", "248", "sel")}${SP.map((s: [string, string, string]) => bentoTile(s[0], s[1], s[2])).join("")}<div class="tile" style="--c:transparent;border:3px dashed var(--line);box-shadow:none;color:var(--mut);align-items:center;justify-content:center;font:900 36px var(--fd)">+</div></div>${grid(LIB)}${xtag("x03", "Nav C · bento: each space is a tile with its count; no hero")}</div>`);

// Journal panel: three ways to keep (or not) the old docked Journal.
X("x04", "Journal A: J opens the Journal tab (current)", desk(jPage(jFeed(), `<div class="row" style="justify-content:space-between"><div class="hero" style="font-size:64px">Today<sup>11</sup></div><span class="lab">from anywhere: <span class="kb">J</span></span></div>`), "", "Journal").replace(/<\/div>$/, xtag("x04", "Journal A · cut the panel; J opens this tab") + "</div>"));
const daySum = (d: string, parts: string, dots: string[]): string => `<div class="row" style="flex-wrap:nowrap;gap:16px;background:var(--well);border-radius:24px;height:64px;padding:0 24px;margin-bottom:12px"><span class="h3" style="font-size:22px;width:150px">${d}</span><span class="row" style="gap:4px;flex-wrap:nowrap">${dots.map((c: string) => `<span style="width:16px;height:16px;border-radius:50%;background:var(--${c})"></span>`).join("")}</span><span class="body" style="flex:1;color:var(--mut)">${parts}</span><span class="h3" style="color:var(--mut)">›</span></div>`;
const weekStrip = (): string => `<div class="row" style="gap:8px;flex-wrap:nowrap">${[["M", "10", ""], ["T", "11", "c"], ["W", "12", "c"], ["T", "13", ""], ["F", "14", "c"], ["S", "15", "c"], ["S", "16", "on"]].map((d: string[]) => `<div style="width:56px;height:72px;border-radius:20px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;${d[2] === "on" ? "background:var(--ink);color:var(--paper)" : "background:var(--well);color:var(--ink)"}"><span style="font:700 16px var(--fu);opacity:.7">${d[0]}</span><span style="font:900 22px var(--fd)">${d[1]}</span>${d[2] === "c" ? `<span style="width:8px;height:8px;border-radius:50%;background:var(--pri)"></span>` : ""}</div>`).join("")}${rb("▦", "sm")}</div>`;
X("x05", "Journal B: calendar jump and folded days", desk(jPage(`${daySum("Saturday", "3 links saved · 1 note", ["cyan", "gold"])}${daySum("Yesterday", "4 links saved · 1 note · 2 done", ["coral", "cyan", "gold"])}<div class="day">Today</div>${bub("Sage green island, warm oak shelves. Keep the worktop pale.", "8:02 AM", strip("Kitchen reno", "coral"))}`, `<div class="row" style="justify-content:space-between;flex-wrap:nowrap"><div class="hero" style="font-size:64px">Today<sup>11</sup></div>${weekStrip()}</div>`, "left:200px;right:200px"), "", "Journal").replace(/<\/div>$/, xtag("x05", "Journal B · week strip jumps to a day; past days fold to one line") + "</div>"));
X("x06", "Journal C: slide-over drawer on Cards", desk(LIBV() + `<div class="dim" style="background:rgba(30,36,52,.22);backdrop-filter:none"></div><div style="position:absolute;right:0;top:0;bottom:0;width:560px;background:var(--paper);border-radius:40px 0 0 40px;box-shadow:var(--sh3);padding:40px;z-index:6"><div class="row" style="justify-content:space-between;flex-wrap:nowrap"><div class="h1" style="font-size:52px">Today<sup>11</sup></div>${rb("✕")}</div><div style="margin-top:24px">${bub("Sage green island, warm oak shelves.", "8:02 AM", strip("Kitchen reno", "coral"))}${bub("Brass pulls, not black.", "8:14 AM", strip("Kitchen reno", "coral"))}${bub("Ask about the onsen ryokan near the river.", "9:10 AM", strip("Kyoto trip", "cyan", true))}</div><div style="position:absolute;left:40px;right:40px;bottom:32px">${field("Write a jot…", false, "", plusBtn())}</div></div>`).replace(/<\/div>$/, xtag("x06", "Journal C · J slides the Journal over Cards") + "</div>"));

